/*
 * Sheet. A molded chassis panel
 * that slides in from an edge, with the seam facing the room. Composes
 * var(--echo-*) only.
 *
 * The `--bleed` trick comes from Base UI's own Drawer recipe: the panel is
 * built wider than it looks and pushed past the edge by that much, so an
 * overscroll rubber-band on iOS reveals more panel instead of the page behind
 * it. The visible width is `--sheet-size`; the bleed is padding nobody sees.
 */

.echo-sheet__backdrop {
  position: fixed;
  /*
   * Above the site chrome: the sticky rail sits on --echo-z-sticky, and an
   * overlay without a z-index renders UNDERNEATH it, which is exactly what
   * this panel once did, with its title and close control hidden behind it.
   */
  z-index: var(--echo-z-overlay, 200);
  inset: 0;
  min-height: 100dvh;
  background: color-mix(in oklab, var(--echo-seam) 88%, black);
  /* Tracks the swipe: drag the panel back and the room comes back with it. */
  opacity: calc(0.62 * (1 - var(--drawer-swipe-progress)));
  transition: opacity var(--echo-duration-pop) cubic-bezier(0.32, 0.72, 0, 1);
}

.echo-sheet__backdrop[data-starting-style],
.echo-sheet__backdrop[data-ending-style] {
  opacity: 0;
}

.echo-sheet__backdrop[data-swiping] {
  transition-duration: 0ms;
}

.echo-sheet__backdrop[data-ending-style] {
  transition-duration: calc(var(--drawer-swipe-strength) * var(--echo-duration-pop));
}

.echo-sheet__viewport {
  --viewport-padding: var(--echo-space-0);
  position: fixed;
  z-index: var(--echo-z-modal, 210);
  inset: 0;
  display: flex;
  padding: var(--viewport-padding);
}

.echo-sheet__viewport[data-side="right"] {
  justify-content: flex-end;
  align-items: stretch;
}
.echo-sheet__viewport[data-side="left"] {
  justify-content: flex-start;
  align-items: stretch;
}
.echo-sheet__viewport[data-side="top"] {
  align-items: flex-start;
}
.echo-sheet__viewport[data-side="bottom"] {
  align-items: flex-end;
}

/* --- the panel ----------------------------------------------------------- */

.echo-sheet__popup {
  --bleed: 3rem;
  --sheet-size: 22rem;
  position: relative;
  box-sizing: border-box;
  padding: var(--echo-space-10);
  background: linear-gradient(158deg, var(--echo-cap) 0%, var(--echo-surface) 42%);
  color: var(--echo-text);
  outline: none;
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: auto;
  transition: transform var(--echo-duration-pop) cubic-bezier(0.32, 0.72, 0, 1);
  will-change: transform;
}

.echo-sheet__popup[data-swiping] {
  user-select: none;
}

.echo-sheet__popup[data-ending-style] {
  transition-duration: calc(var(--drawer-swipe-strength) * var(--echo-duration-pop));
}

/* Left / right: full height, the lit seam on the inward edge. */
.echo-sheet__popup[data-side="right"],
.echo-sheet__popup[data-side="left"] {
  height: 100%;
  width: calc(var(--sheet-size) + var(--bleed));
  max-width: calc(100vw - 2.5rem + var(--bleed));
  transform: translateX(var(--drawer-swipe-movement-x));
}

.echo-sheet__popup[data-side="right"] {
  margin-right: calc(-1 * var(--bleed));
  padding-right: calc(26px + var(--bleed));
  border-left: var(--echo-border-hairline, 1px) solid var(--echo-seam);
  box-shadow:
    inset 1px 0 0 color-mix(in oklab, var(--echo-cap-highlight) 40%, transparent),
    -26px 0 60px -20px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent);
}
.echo-sheet__popup[data-side="right"][data-starting-style],
.echo-sheet__popup[data-side="right"][data-ending-style] {
  transform: translateX(calc(100% - var(--bleed) + var(--viewport-padding) + 2px));
}

.echo-sheet__popup[data-side="left"] {
  margin-left: calc(-1 * var(--bleed));
  padding-left: calc(26px + var(--bleed));
  border-right: var(--echo-border-hairline, 1px) solid var(--echo-seam);
  box-shadow:
    inset -1px 0 0 color-mix(in oklab, var(--echo-cap-highlight) 40%, transparent),
    26px 0 60px -20px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent);
}
.echo-sheet__popup[data-side="left"][data-starting-style],
.echo-sheet__popup[data-side="left"][data-ending-style] {
  transform: translateX(calc(-100% + var(--bleed) - var(--viewport-padding) - 2px));
}

/* Top / bottom: full width. */
.echo-sheet__popup[data-side="top"],
.echo-sheet__popup[data-side="bottom"] {
  width: 100%;
  max-height: calc(100dvh - 3rem + var(--bleed));
  transform: translateY(var(--drawer-swipe-movement-y));
}

.echo-sheet__popup[data-side="bottom"] {
  margin-bottom: calc(-1 * var(--bleed));
  padding-bottom: calc(26px + var(--bleed));
  border-top: var(--echo-border-hairline, 1px) solid var(--echo-seam);
  border-radius: var(--echo-radius-2xl) var(--echo-radius-2xl) 0 0;
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--echo-cap-highlight) 40%, transparent),
    0 -26px 60px -20px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent);
}
.echo-sheet__popup[data-side="bottom"][data-starting-style],
.echo-sheet__popup[data-side="bottom"][data-ending-style] {
  transform: translateY(calc(100% - var(--bleed) + var(--viewport-padding) + 2px));
}

.echo-sheet__popup[data-side="top"] {
  margin-top: calc(-1 * var(--bleed));
  padding-top: calc(26px + var(--bleed));
  border-bottom: var(--echo-border-hairline, 1px) solid var(--echo-seam);
  border-radius: 0 0 var(--echo-radius-2xl) var(--echo-radius-2xl);
  box-shadow:
    inset 0 -1px 0 color-mix(in oklab, var(--echo-cap-highlight) 40%, transparent),
    0 26px 60px -20px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent);
}
.echo-sheet__popup[data-side="top"][data-starting-style],
.echo-sheet__popup[data-side="top"][data-ending-style] {
  transform: translateY(calc(-100% + var(--bleed) - var(--viewport-padding) - 2px));
}

/* --- contents ------------------------------------------------------------ */

.echo-sheet__content {
  display: grid;
  gap: var(--echo-space-3);
  align-content: start;
  height: 100%;
}

.echo-sheet__title {
  margin: 0;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-lg);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-tight, -0.01em);
  color: var(--echo-text);
}

.echo-sheet__desc {
  margin: 0 0 var(--echo-space-5);
  font-size: var(--echo-text-sm);
  line-height: var(--echo-leading-body, 1.55);
  color: var(--echo-text-dim);
}

/* --- controls ------------------------------------------------------------ */

.echo-sheet__trigger {
  display: inline-flex;
  align-items: center;
  gap: var(--echo-space-4);
  height: calc(40px * var(--echo-density, 1));
  padding: 0 var(--echo-space-8);
  border: 0;
  border-radius: var(--echo-radius-lg);
  cursor: pointer;
  color: var(--echo-text);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-md);
  background: linear-gradient(
    180deg,
    var(--echo-cap-highlight) 0%,
    color-mix(in oklab, var(--echo-cap-highlight) 50%, var(--echo-cap)) 40%,
    var(--echo-cap) 62%,
    var(--echo-cap-shadow) 100%
  );
  box-shadow:
    inset 0 1.5px 0 rgb(255 255 255 / calc(0.42 * var(--echo-gloss, 1))),
    inset 0 -3px 4px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.5 * var(--echo-shade, 1) * 100%), transparent),
    0 calc(4px + 1px * var(--lift, 0) - 3px * var(--press, 0)) 0 var(--echo-seam),
    0 calc(9px + 5px * var(--lift, 0) - 6px * var(--press, 0)) calc(14px + 10px * var(--lift, 0) - 9px * var(--press, 0))
      color-mix(in oklab, var(--echo-cast-ink, black) calc(0.55 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
  /* usePressable owns the transform: lift, lean, travel onto the seam. */
}

.echo-sheet__trigger:focus-visible,
.echo-sheet__close:focus-visible,
.echo-sheet__action:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}

/*
 * The close control is pinned to the panel's VISIBLE corner, which on a
 * right-hand sheet is inset by the bleed rather than by the padding.
 */
.echo-sheet__close {
  position: absolute;
  top: 16px;
  display: grid;
  place-items: center;
  width: 30px;
  height: calc(30px * var(--echo-density, 1));
  border: 0;
  border-radius: var(--echo-radius-md);
  cursor: pointer;
  background: var(--echo-cap);
  color: var(--echo-text-dim);
  font-size: var(--echo-text-sm);
  line-height: var(--echo-leading-none, 1);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--echo-cap-highlight) 60%, transparent),
    0 calc(2px - 1.5px * var(--press, 0)) 0 var(--echo-cap-shadow);
}

.echo-sheet__popup[data-side="right"] .echo-sheet__close,
.echo-sheet__popup[data-side="top"] .echo-sheet__close,
.echo-sheet__popup[data-side="bottom"] .echo-sheet__close {
  inset-inline-end: calc(16px + var(--bleed));
}
.echo-sheet__popup[data-side="left"] .echo-sheet__close {
  inset-inline-end: 16px;
}
.echo-sheet__popup[data-side="top"] .echo-sheet__close {
  top: calc(16px + var(--bleed));
}

@media (hover: hover) {
  .echo-sheet__close:hover {
    color: var(--echo-text);
  }
}

.echo-sheet__action {
  height: calc(36px * var(--echo-density, 1));
  padding: 0 var(--echo-space-7);
  border: 0;
  border-radius: var(--echo-radius-lg);
  cursor: pointer;
  background: var(--echo-cap);
  color: var(--echo-text);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--echo-cap-highlight) 60%, transparent),
    0 calc(2px - 1.5px * var(--press, 0)) 0 var(--echo-cap-shadow);
}

/*
 * Reduced motion. The slide is the sheet's whole identity, so it is shortened
 * rather than removed — a panel that teleports in reads as a rendering bug,
 * and Echo's rule is that motion collapses, not that it vanishes.
 */
@media (prefers-reduced-motion: reduce) {
  .echo-sheet__popup,
  .echo-sheet__backdrop {
    transition-duration: var(--echo-duration-tick);
  }
}

/*
 * Coarse-pointer targets.
 *
 * These already clear WCAG 2.2 2.5.8's 24px. This is the other
 * threshold: the 44px both platform guidelines use, which is about a
 * fingertip rather than about conformance.
 *
 * Gated on `@media (pointer: coarse)` so the desktop rendering does not move
 * — these are "passing AA but under the
 * platform guideline", not broken. Pagination is first among them because
 * people tap it repeatedly, which is exactly when a 30px target starts
 * costing mis-taps.
 */
@media (pointer: coarse) {
  .echo-sheet__close {
    width: 44px;
    height: 44px;
  }

  .echo-sheet__trigger {
    min-height: 44px;
  }
}

"use client";

/**
 * Sheet. A panel that slides in
 * from an edge: the console side panel and the mobile nav.
 *
 * BUILT ON BASE UI'S `Drawer`, NOT ON `Dialog`. It was first planned as
 * "Dialog + side variant", which was decided before Base UI 1.6 shipped a real
 * Drawer primitive. Drawer gives swipe-to-dismiss, the swipe-progress custom
 * properties the backdrop tracks, and the overscroll bleed — none of which a
 * Dialog with a translated popup would have, and all of which are exactly what
 * a mobile nav needs. Dialog would have been a hand-rolled worse version.
 *
 *   <Sheet side="right">
 *     <Sheet.Trigger>Open</Sheet.Trigger>
 *     <Sheet.Content title="Channels" description="Pick one.">
 *       …
 *     </Sheet.Content>
 *   </Sheet>
 *
 * `side` sets BOTH the swipe direction and the edge the panel is pinned to, so
 * a right-hand sheet cannot end up dismissing on an upward swipe — the pair is
 * one decision, and splitting it across two props is how they drift apart.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import { createContext, useContext, type ComponentProps, type ReactNode } from "react";
import { Drawer } from "@base-ui/react/drawer";
import { useSoundOptional } from "echo-ui-core/sound";
import { usePressable } from "echo-ui-core/tactile";
import "./sheet.css";

const cx = (...c: (string | undefined)[]) => c.filter(Boolean).join(" ");

/** Narrow Base UI's string-or-function className to a plain string for skinning. */
type Skin<T> = Omit<T, "className"> & { className?: string };

export type SheetSide = "left" | "right" | "top" | "bottom";

export interface SheetProps extends Omit<ComponentProps<typeof Drawer.Root>, "swipeDirection"> {
  /** Edge the sheet is pinned to, and the direction it swipes away. Default "right". */
  side?: SheetSide;
}

export interface SheetContentProps
  // `title` is omitted from the passthrough because Drawer.Popup inherits the
  // DOM title attribute (a string tooltip) and ours is the panel's heading.
  extends Omit<Skin<ComponentProps<typeof Drawer.Popup>>, "title"> {
  /**
   * Accessible name for the panel. Required in practice: a drawer with no
   * title is an unlabelled region to anyone not looking at it.
   */
  title?: ReactNode;
  description?: ReactNode;
  /** Show the corner close control. Default true. */
  showClose?: boolean;
  /**
   * Where the panel mounts. Defaults to <body>. Pass an element inside a
   * scoped theme (`createEchoTheme(seed, { selector })`) and the panel wears
   * that theme too — mounted on <body>, it can only read the :root one.
   */
  container?: ComponentProps<typeof Drawer.Portal>["container"];
  children?: ReactNode;
}

/**
 * `side` has to reach Content (to pin the edge) as well as Root (to set the
 * swipe axis), and Content is a sibling subtree rather than a prop away — so
 * it travels by context. A module-level variable would be smaller and wrong:
 * two sheets with different sides on one page would overwrite each other, and
 * on the server every request would share the same slot.
 */
const SheetSideContext = createContext<SheetSide>("right");

/** Swipe axis for an edge. Pinning and dismissal are one decision, not two. */
const SWIPE: Record<SheetSide, "left" | "right" | "up" | "down"> = {
  left: "left",
  right: "right",
  top: "up",
  bottom: "down",
};

function SheetRoot({ side = "right", onOpenChange, children, ...props }: SheetProps) {
  const sound = useSoundOptional();

  return (
    <Drawer.Root
      swipeDirection={SWIPE[side]}
      onOpenChange={(open, eventDetails) => {
        if (open) sound?.play("transition");
        onOpenChange?.(open, eventDetails);
      }}
      {...props}
    >
      {/*
        Base UI allows children to be a payload render function (for
        handle-driven sheets), so the provider wraps the RESULT in that case
        rather than the function — narrowing children to ReactNode here would
        quietly drop a Drawer capability.
      */}
      {typeof children === "function"
        ? (arg: { payload: unknown }) => <SheetSideContext.Provider value={side}>{children(arg)}</SheetSideContext.Provider>
        : <SheetSideContext.Provider value={side}>{children}</SheetSideContext.Provider>}
    </Drawer.Root>
  );
}

/* The trigger, the close key and the actions are molded caps, so they press
   like the library's keys (usePressable). */
function SheetTrigger({ className, ...props }: Skin<ComponentProps<typeof Drawer.Trigger>>) {
  const press = usePressable<HTMLButtonElement>(props, { tilt: 3 });
  return <Drawer.Trigger className={cx("echo-sheet__trigger", className)} {...props} {...press} />;
}

function SheetCloseKey() {
  const press = usePressable<HTMLButtonElement>({}, { lift: 0, travel: 1.5, tilt: 0 });
  return (
    <Drawer.Close className="echo-sheet__close" aria-label="Close" {...press}>
      ✕
    </Drawer.Close>
  );
}

function SheetContent({
  title,
  description,
  showClose = true,
  className,
  container,
  children,
  ...props
}: SheetContentProps) {
  const side = useContext(SheetSideContext);

  return (
    <Drawer.Portal container={container}>
      <Drawer.Backdrop className="echo-sheet__backdrop" />
      <Drawer.Viewport className="echo-sheet__viewport" data-side={side}>
        <Drawer.Popup className={cx("echo-sheet__popup", className)} data-side={side} {...props}>
          <Drawer.Content className="echo-sheet__content">
            {title != null ? (
              <Drawer.Title className="echo-sheet__title">{title}</Drawer.Title>
            ) : null}
            {description != null ? (
              <Drawer.Description className="echo-sheet__desc">{description}</Drawer.Description>
            ) : null}
            {children}
          </Drawer.Content>
          {showClose ? (
            <SheetCloseKey />
          ) : null}
        </Drawer.Popup>
      </Drawer.Viewport>
    </Drawer.Portal>
  );
}

function SheetClose({ className, ...props }: Skin<ComponentProps<typeof Drawer.Close>>) {
  const press = usePressable<HTMLButtonElement>(props, { travel: 1.5, tilt: 3 });
  return <Drawer.Close className={cx("echo-sheet__action", className)} {...props} {...press} />;
}

// Assembled into `Sheet` in index.ts, which isn't a client module.
export { SheetRoot, SheetTrigger, SheetContent, SheetClose };

/**
 * The entry point for Sheet, deliberately NOT a client module: the parts are
 * attached here, from named client exports. Attached inside the "use client"
 * file, they didn't survive a server component's import, so Sheet.Trigger was
 * undefined in a Next.js page or layout and the build failed.
 */
import { SheetRoot, SheetTrigger, SheetContent, SheetClose } from "./sheet";

export const Sheet = Object.assign(SheetRoot, {
  Trigger: SheetTrigger,
  Content: SheetContent,
  Close: SheetClose,
});
export type { SheetProps, SheetContentProps, SheetSide } from "./sheet";
